import {animateLadderBoard,revealLadderResult} from './ladder-effects.js?v=20261010-member-fixes';
import {trace,layout,lanePath,minBoardWidth} from './whozzie.js?v=20261010-member-fixes';
import {memberName} from './teams.js?v=20261010-member-fixes';
import {restrictionActive} from './restrictions.js?v=20261010-member-fixes';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const colours=['#4976b7','#d89445','#7b9a77','#aa79a9','#ca7475','#648c9d','#a79853','#818ac0','#cc925e','#6aab99','#a6816a','#a1718b'];
const previewRooms=new Map();
const approved=actor=>actor?.user_metadata?.status==='approved'&&!restrictionActive(actor.user_metadata);
const SLOT_MS=4000,TRACE_MS=2800;
const outcomesFor=(capacity,losers)=>Array.from({length:capacity},(_,i)=>i<losers?'꽝':'통과');
function settingsFields(capacity=4,losers=1){return `<div class="tool-fields"><label>참여 인원<select name="capacity">${Array.from({length:11},(_,i)=>`<option value="${i+2}" ${i+2===capacity?'selected':''}>${i+2}명</option>`).join('')}</select></label><label>꽝 인원<select name="losers">${Array.from({length:capacity-1},(_,i)=>`<option value="${i+1}" ${i+1===losers?'selected':''}>${i+1}명</option>`).join('')}</select></label></div>`;}
function bindCapacity(form){form.elements.capacity.onchange=()=>{const capacity=Number(form.elements.capacity.value),losers=Math.min(Number(form.elements.losers.value),capacity-1);form.elements.losers.innerHTML=Array.from({length:capacity-1},(_,i)=>`<option value="${i+1}" ${i+1===losers?'selected':''}>${i+1}명</option>`).join('');};}
export function ladderRoundView(round,width=850){
  const boardWidth=Math.max(minBoardWidth(round.ladder.columns),Math.min(width,1400)),geometry=layout(boardWidth,round.ladder);
  const lanes=round.seats.map((player,column)=>({...trace(round.ladder,column),player}));
  const html=`<div class="ladder-paper-scroll"><svg class="ladder-paper" viewBox="0 0 ${boardWidth} ${geometry.height}" width="${boardWidth}" height="${geometry.height}" role="img" aria-label="참여자가 차례대로 진행하는 사다리"><g>${lanes.map((lane,column)=>`<line class="room-ladder-line" x1="${geometry.x(column)}" y1="${geometry.lineTop(column)}" x2="${geometry.x(column)}" y2="${geometry.flapTop(column)}"/><rect data-name-column="${column}" class="ladder-name-chip" style="stroke:${colours[lane.player]}" x="${geometry.x(column)-Math.min(geometry.labelWidth,160)/2}" y="${geometry.chipTop(column)}" width="${Math.min(geometry.labelWidth,160)}" height="40" rx="8"/><text class="ladder-name" x="${geometry.x(column)}" y="${geometry.chipTop(column)+25}" text-anchor="middle">${column+1}. ${esc(round.players[lane.player].name.slice(0,12))}</text><rect data-slot-chip="${column}" class="ladder-result-chip" x="${geometry.x(column)-geometry.flapWidth/2}" y="${geometry.flapTop(column)}" width="${geometry.flapWidth}" height="44" rx="7"/><text data-slot="${column}" class="ladder-outcome" x="${geometry.x(column)}" y="${geometry.flapTop(column)+28}" text-anchor="middle">?</text>`).join('')}${round.ladder.rungs.map((row,r)=>row.map((rung,gap)=>rung?`<line class="room-ladder-line" x1="${geometry.x(gap)}" y1="${geometry.rungY(r,gap)}" x2="${geometry.x(gap+1)}" y2="${geometry.rungY(r,gap)}"/>`:'').join('')).join('')}</g>${lanes.map((lane,column)=>{const path=lanePath(lane,geometry);return `<path data-ladder-path="${column}" class="room-ladder-route" stroke="${colours[lane.player]}" d="${path.d}" pathLength="1" stroke-dasharray="1" stroke-dashoffset="1"/><g data-ladder-ball="${column}" class="ladder-ball" style="opacity:0"><circle r="11" fill="#fff" stroke="${colours[lane.player]}" stroke-width="2.5"/><path d="M-6 -8 Q1 0 -6 8 M6 -8 Q-1 0 6 8" fill="none" stroke="#c97671" stroke-width="1.5"/></g>`;}).join('')}</svg></div>`;
  return{html,lanes};
}
function service(db,actor){
  if(db){const rpc=async(name,args)=>{const{data,error}=await db.rpc(name,args);if(error)throw error;return data;};return{list:()=>rpc('list_ladder_rooms'),create:(capacity,losers)=>rpc('create_ladder_room',{p_capacity:capacity,p_losers:losers}),settings:(id,capacity,losers)=>rpc('update_ladder_settings',{p_room:id,p_capacity:capacity,p_losers:losers}),join:code=>rpc('join_ladder_room',{p_code:code}),get:id=>rpc('get_ladder_room',{p_room:id}),ready:(id,value)=>rpc('set_ladder_ready',{p_room:id,p_ready:value}),leave:id=>rpc('leave_ladder_room',{p_room:id})};}
  const guard=()=>{if(!approved(actor))throw new Error('Approved member required');};
  return{async list(){guard();return [...previewRooms.values()].filter(room=>room.phase==='waiting').map(room=>({...room,count:room.players.length,host:room.players[0]?.nickname}));},async create(capacity,losers){guard();const title='사다리 게임',outcomes=outcomesFor(capacity,losers);const room={id:crypto.randomUUID(),code:crypto.randomUUID().slice(0,6).toUpperCase(),title,capacity:outcomes.length,losers,host_id:actor.id,phase:'waiting',revision:1,server_time:new Date().toISOString(),players:[{id:actor.id,...actor.user_metadata,ready:false}]};previewRooms.set(room.id,room);return structuredClone(room);},async settings(id,capacity,losers){guard();const room=previewRooms.get(id);if(room.host_id!==actor.id)throw new Error('Host required');if(room.players.length>capacity)throw new Error('Capacity below participants');Object.assign(room,{capacity,losers,revision:room.revision+1});for(const p of room.players)p.ready=false;return structuredClone(room);},async join(code){guard();const room=[...previewRooms.values()].find(item=>item.code===code);if(!room)throw new Error('Room not found');return structuredClone(room);},async get(id){guard();return structuredClone(previewRooms.get(id));},async ready(id,value){guard();const room=previewRooms.get(id);room.players.find(item=>item.id===actor.id).ready=value;room.revision++;return structuredClone(room);},async leave(id){previewRooms.delete(id);}};
}
function friendly(error){const message=error?.message||'';if(/Host required/.test(message))return '방장만 설정을 변경할 수 있습니다.';if(/Capacity below/.test(message))return '이미 입장한 인원보다 작게 설정할 수 없습니다.';if(/Room full/.test(message))return '대기방이 가득 찼습니다.';if(/already starting/.test(message))return '이미 시작한 게임입니다.';if(/Room not found|Room closed|membership required/.test(message))return '대기방이 종료되었거나 참가할 수 없습니다.';if(/Approved member/.test(message))return '로그인한 승인 회원만 참여할 수 있습니다.';if(/limit/.test(message))return '방 생성 횟수를 초과했습니다. 잠시 후 다시 시도해 주세요.';return '대기방을 갱신하지 못했어요. 연결 상태를 확인해 주세요.';}
export async function renderOnlineLadder(main,{db,actor,isCurrent=()=>true,onAuth=()=>{},signal,notify=()=>{}}={}){
  const api=service(db,actor);let current=null,busy=false,generation=0,clockOffset=0,boardKey='',boardData=null,stopEffects=()=>{};
  main.innerHTML=`<section class="tool-page ladder-room-page"><div class="board-heading"><div><h1>사다리 게임</h1></div></div><p class="form-error" id="room-error" role="alert"></p><div id="ladder-lobby"></div><section id="ladder-room" hidden></section></section>`;
  const root=main.querySelector('.ladder-room-page'),find=selector=>root.querySelector(selector),alive=()=>isCurrent()&&!signal?.aborted&&main.contains(root);
  function error(message){find('#room-error').textContent=message;}
  function lobby(){find('#ladder-lobby').innerHTML=!approved(actor)?'<div class="room-login"><strong>로그인하고 함께 참여하세요.</strong><p>승인된 회원이 입장해 모두 준비하면 게임이 시작됩니다.</p><button class="primary" id="room-login-button" type="button">로그인</button></div>':`<div class="room-lobby-grid"><div class="tool-card"><h2>대기방 만들기</h2><form id="room-create-form">${settingsFields()}<p class="form-note">방을 만든 회원이 방장입니다. 시작 전 방장이 인원과 꽝 수를 설정합니다.</p><button class="primary" type="submit">방 만들기</button></form></div><div class="tool-card room-list-card"><h2>대기방 목록</h2><div class="room-list" aria-live="polite"><div class="empty">대기방을 불러오는 중입니다.</div></div></div></div>`;
    find('#room-login-button')?.addEventListener('click',onAuth);const form=find('#room-create-form');if(form){bindCapacity(form);form.onsubmit=event=>{event.preventDefault();void change(()=>api.create(Number(form.elements.capacity.value),Number(form.elements.losers.value)));};}}
  async function refreshList(){if(!alive()||current||!approved(actor))return;const id=++generation;try{const rooms=await api.list();if(!alive()||id!==generation||current)return;const list=find('.room-list');const content=rooms.length?rooms.map(room=>`<div class="room-list-item"><div><strong>${esc(room.host)}님의 사다리</strong><span>참여 ${room.count}/${room.capacity}명</span></div><button class="secondary" type="button" data-room-code="${esc(room.code)}" aria-label="${esc(room.host)}님의 방 입장" ${room.count>=room.capacity?'disabled':''}>입장</button></div>`).join(''):'<div class="empty">열려 있는 대기방이 없습니다.</div>';if(list.innerHTML!==content){list.innerHTML=content;for(const button of list.querySelectorAll('[data-room-code]'))button.onclick=()=>void change(()=>api.join(button.dataset.roomCode));}}catch(failure){if(alive()&&id===generation)error(friendly(failure));}}
  async function change(action){if(busy||!alive())return;busy=true;generation++;error('');try{const room=await action();if(!alive())return;current=room;clockOffset=db?Date.parse(room.server_time)-Date.now():0;drawRoom();}catch(failure){if(alive())error(friendly(failure));}finally{busy=false;}}
  function drawRoom(){find('#ladder-lobby').hidden=true;find('#ladder-room').hidden=false;const me=current.players.find(player=>player.id===actor?.id),ready=current.players.filter(player=>player.ready).length;find('#ladder-room').innerHTML=`<div class="room-heading"><div><span class="room-eyebrow">${esc(current.players.find(player=>player.id===current.host_id)?.nickname||'방장')}님의 방</span><h2>${esc(current.title)}</h2><p>준비 ${ready}/${current.capacity}명 · 인원이 모두 입장하고 준비하면 시작합니다.</p></div><div class="room-heading-buttons"><button type="button" class="text-button" id="room-leave">나가기</button></div></div>${current.host_id===actor?.id&&current.phase==='waiting'?`<form class="tool-card room-settings" id="room-settings-form">${settingsFields(current.capacity,current.losers)}<button class="secondary" type="submit">설정 변경</button></form>`:''}<div class="room-player-grid">${Array.from({length:current.capacity},(_,index)=>{const player=current.players[index];return player?`<div class="room-player" data-ready="${player.ready}"><span class="room-avatar" style="--player-colour:${colours[index]}">${esc(player.nickname[0])}</span><strong class="member-identity">${memberName(player.nickname,player.team,player.region,player.staff_role)}</strong><span class="room-ready-status">${player.ready?'준비 완료':'준비 중'}${player.id===current.host_id?' · 방장':''}</span></div>`:'<div class="room-player empty-seat"><span>+</span><p>입장 대기</p></div>';}).join('')}</div><div class="room-ready-bar"><p id="room-stage" role="status"></p><button class="primary" type="button" id="room-ready" aria-pressed="${Boolean(me?.ready)}">${me?.ready?'준비 취소':'준비'}</button></div><div id="room-game"></div>`;
    const settingsForm=find('#room-settings-form');if(settingsForm){bindCapacity(settingsForm);settingsForm.onsubmit=event=>{event.preventDefault();void change(()=>api.settings(current.id,Number(settingsForm.elements.capacity.value),Number(settingsForm.elements.losers.value)));};}
    find('#room-ready').disabled=!me||['running','finished','closed'].includes(current.phase);find('#room-ready').onclick=()=>void change(()=>api.ready(current.id,!me.ready));find('#room-leave').onclick=async()=>{if(busy)return;busy=true;generation++;try{await api.leave(current.id);current=null;boardKey='';stopEffects();find('#ladder-room').hidden=true;find('#ladder-lobby').hidden=false;await refreshList();}catch(failure){if(alive())error(friendly(failure));}finally{busy=false;}};boardKey='';tick();}
  function mountBoard(holder,round,key,elapsed){key+=`:${root.clientWidth}`;if(boardKey===key&&holder.querySelector('.ladder-paper'))return;stopEffects();boardKey=key;boardData=ladderRoundView(round,Math.max(360,root.clientWidth-40));holder.innerHTML=`<div class="room-game-card">${boardData.html}<div class="room-results" aria-live="polite">${boardData.lanes.map((lane,column)=>`<div data-result="${column}" hidden><span>${column+1}. ${esc(round.players[lane.player].name)}</span><strong>${esc(round.outcomes[round.slots[lane.end]])}</strong></div>`).join('')}</div></div>`;stopEffects=animateLadderBoard(holder,elapsed,SLOT_MS,TRACE_MS);}

  function tick(){if(!alive())return;if(!current)return;const now=Date.now()+clockOffset,elapsed=now-Date.parse(current.start_at),remaining=Math.ceil(-elapsed/1000);const stage=find('#room-stage');if(current.phase==='closed'){stage.textContent='대기방이 종료되었습니다.';find('#room-ready').disabled=true;return;}if(!current.start_at){stage.textContent='모두 준비되면 5초 후 시작합니다.';return;}if(remaining>0){if(stage.dataset.countdown!==String(remaining)){stage.dataset.countdown=String(remaining);stage.innerHTML=`<span class="room-countdown">${remaining}</span> 게임 시작까지`;}return;}find('#room-ready').disabled=true;if(!current.round){stage.textContent='게임을 불러오고 있어요.';return;}mountBoard(find('#room-game'),current.round,`room:${current.id}:${current.start_at}`,elapsed);reveal(find('#room-game'),current.round,elapsed);const step=Math.floor(elapsed/SLOT_MS);stage.textContent=step>=current.capacity?'모든 결과가 공개되었습니다.':`${step+1}번 ${current.round.players[current.round.seats[step]].name} · ${elapsed%SLOT_MS<TRACE_MS?'진행 중':'결과 공개'}`;}
  function reveal(holder,round,elapsed){const lanes=boardData.lanes,step=Math.floor(elapsed/SLOT_MS);for(const chip of holder.querySelectorAll('[data-name-column]'))chip.dataset.active=String(Number(chip.dataset.nameColumn)===step);for(let column=0;column<lanes.length;column++)if(elapsed>=column*SLOT_MS+TRACE_MS){const lane=lanes[column];revealLadderResult(holder,column,lane.end,round.outcomes[round.slots[lane.end]],elapsed-column*SLOT_MS-TRACE_MS<800);}}

  async function poll(){if(!alive()||busy)return;if(!current){await refreshList();return;}const id=++generation;try{const room=await api.get(current.id);if(!alive()||id!==generation)return;const redraw=room.revision!==current.revision||room.phase!==current.phase;current=room;clockOffset=db?Date.parse(room.server_time)-Date.now():0;if(redraw)drawRoom();else tick();}catch(failure){if(alive()&&id===generation){error(friendly(failure));find('#room-ready')?.setAttribute('disabled','');}}}
  const onVisibility=()=>{boardKey='';tick();};document.addEventListener('visibilitychange',onVisibility);
  const timer=setInterval(tick,150),pollTimer=setInterval(()=>void poll(),1500);signal?.addEventListener('abort',()=>{clearInterval(timer);clearInterval(pollTimer);stopEffects();document.removeEventListener('visibilitychange',onVisibility);generation++;if(current)void api.leave(current.id).catch(()=>{});},{once:true});
  lobby();await refreshList();const code=new URLSearchParams(location.hash.split('?')[1]).get('room');if(alive()&&approved(actor)&&code)await change(()=>api.join(code.toUpperCase()));
}
